<?php
declare(strict_types=1);

require __DIR__.'/bootstrap.php';
require tamiran_private_root().'/v2-core.php';
$smsService=tamiran_private_root().'/sms-service.php';if(is_file($smsService))require_once$smsService;

function quality_payload(PDO $pdo,array $scope):array
{
    v2_require_permission($scope,'qc.view',['quality_control','technician'],'مشاهده کنترل کیفیت مجاز نیست.');$templates=$pdo->prepare('SELECT * FROM repair_qc_templates WHERE shop_id=:shop AND is_active=1 ORDER BY workflow_code,source,id');$templates->execute(['shop'=>$scope['shop_id']]);$list=$templates->fetchAll();$item=$pdo->prepare('SELECT * FROM repair_qc_template_items WHERE template_id=:template ORDER BY sort_order,id');foreach($list as&$template){$item->execute(['template'=>$template['id']]);$template['items']=$item->fetchAll();}unset($template);$runs=$pdo->prepare('SELECT q.*,c.receipt_number,u.display_name AS performer_name FROM repair_qc_runs q INNER JOIN repair_cases c ON c.id=q.case_id INNER JOIN tamiran_users u ON u.id=q.performed_by_user_id WHERE q.shop_id=:shop AND c.branch_id=:branch ORDER BY q.completed_at DESC LIMIT 500');$runs->execute(['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);return['templates'=>$list,'runs'=>$runs->fetchAll()];
}

function quality_route_after_run(PDO $pdo,array $scope,int $caseId,string $result,?string $failure,?string $limitations,string $idempotency):array
{
    $target=$result==='failed'?'qc_rework':($result==='conditional'?'qc_conditional':'finance_pending');
    $fresh=v2_case($pdo,$scope,$caseId);
    if((string)$fresh['process_status']!==$target&&$fresh['process_status']==='qc_pending'){
        return v2_transition($pdo,$scope,$caseId,$target,$result==='failed'?$failure:($limitations??'تکمیل QC'),(int)$fresh['lock_version'],$idempotency.':transition',true);
    }
    return$fresh;
}

function quality_run(PDO $pdo,array $scope,array $input):array
{
    v2_require_permission($scope,'qc.perform',['quality_control'],'ثبت QC فقط برای مسئول کنترل کیفیت یا مدیر مجاز است.');$caseId=(int)($input['caseId']??0);$templateId=(int)($input['templateId']??0);$idempotency=v2_text($input['idempotencyKey']??tamiran_request_id(),'شناسه یکتای QC',160);$requestedResult=(string)($input['result']??'passed');if(!in_array($requestedResult,['passed','failed','conditional'],true))throw new TamiranApiException('نتیجه QC معتبر نیست.');if($requestedResult==='conditional'&&!v2_has_permission($scope,'qc.conditional',['repair_manager']))throw new TamiranApiException('ثبت قبول مشروط فقط با مجوز مدیر ممکن است.',403);$failure=v2_text($input['failureReason']??'','علت مردودی',1000,false);$limitations=v2_text($input['conditionalLimitations']??'','محدودیت مشروط',1000,false);$answers=is_array($input['items']??null)?$input['items']:[];$customAnswers=is_array($input['customItems']??null)?$input['customItems']:[];
    $replay=$pdo->prepare('SELECT public_id,result,failure_reason,conditional_limitations FROM repair_qc_runs WHERE shop_id=:shop AND case_id=:case AND idempotency_key=:idempotency LIMIT 1');$replay->execute(['shop'=>$scope['shop_id'],'case'=>$caseId,'idempotency'=>$idempotency]);$replayRow=$replay->fetch();if(is_array($replayRow)){$transition=quality_route_after_run($pdo,$scope,$caseId,(string)$replayRow['result'],$replayRow['failure_reason'],$replayRow['conditional_limitations'],$idempotency);return['completed'=>true,'replayed'=>true,'publicId'=>$replayRow['public_id'],'result'=>$replayRow['result'],'case'=>$transition];}
    $pdo->beginTransaction();try{$case=v2_case($pdo,$scope,$caseId,true);if($case['process_status']!=='qc_pending')throw new TamiranApiException('پرونده در مرحله QC نیست.',409);$settings=$pdo->prepare('SELECT operation_mode,allow_self_qc FROM repair_shops WHERE id=:shop');$settings->execute(['shop'=>$scope['shop_id']]);$shop=$settings->fetch();$self=(int)$case['primary_technician_user_id']===(int)$scope['actor']['id'];if($self&&(!is_array($shop)||$shop['operation_mode']!=='single_user'||!(bool)$shop['allow_self_qc']))throw new TamiranApiException('ثبت QC کار خود فقط در حالت تک‌نفره و با فعال‌سازی تنظیم مدیر مجاز است.',409);$template=$pdo->prepare('SELECT id,workflow_code FROM repair_qc_templates WHERE id=:id AND shop_id=:shop AND is_active=1');$template->execute(['id'=>$templateId,'shop'=>$scope['shop_id']]);$templateRow=$template->fetch();if(!is_array($templateRow)||$templateRow['workflow_code']!==$case['workflow_code'])throw new TamiranApiException('چک‌لیست با گردش صنف پرونده تطابق ندارد.',409);$required=$pdo->prepare('SELECT id,is_required,requires_evidence_on_fail FROM repair_qc_template_items WHERE template_id=:template ORDER BY sort_order,id');$required->execute(['template'=>$templateId]);$requiredRows=$required->fetchAll();$allowedItems=[];foreach($requiredRows as$item)$allowedItems[(int)$item['id']]=$item;$answerMap=[];foreach($answers as$answer){$answerId=(int)($answer['templateItemId']??0);if(!isset($allowedItems[$answerId]))throw new TamiranApiException('یکی از تست‌ها متعلق به قالب انتخاب‌شده نیست.',409);$answerMap[$answerId]=$answer;}foreach($requiredRows as$requiredItem){$answer=$answerMap[(int)$requiredItem['id']]??null;if((bool)$requiredItem['is_required']&&(!is_array($answer)||in_array((string)($answer['result']??''),['','not_tested'],true)))throw new TamiranApiException('همه موارد اجباری چک‌لیست باید تکمیل شوند.');if(is_array($answer)&&($answer['result']??'')==='failed'&&(bool)$requiredItem['requires_evidence_on_fail']&&empty($answer['evidenceFileId'])&&trim((string)($answer['notes']??''))==='')throw new TamiranApiException('برای مورد مردود، مستند یا توضیح الزامی است.');}
        $existing=$pdo->prepare('SELECT public_id,result,failure_reason,conditional_limitations FROM repair_qc_runs WHERE case_id=:case AND idempotency_key=:idempotency LIMIT 1 FOR UPDATE');$existing->execute(['case'=>$caseId,'idempotency'=>$idempotency]);$replayed=$existing->fetch();if(is_array($replayed)){$pdo->commit();$transition=quality_route_after_run($pdo,$scope,$caseId,(string)$replayed['result'],$replayed['failure_reason'],$replayed['conditional_limitations'],$idempotency);return['completed'=>true,'replayed'=>true,'publicId'=>$replayed['public_id'],'result'=>$replayed['result'],'case'=>$transition];}
        $hasFailed=false;foreach(array_merge($answers,$customAnswers)as$answer)if(($answer['result']??'')==='failed')$hasFailed=true;$result=$hasFailed?'failed':$requestedResult;if($result==='failed'&&$failure===null)throw new TamiranApiException('برای QC مردود، علت بازکاری الزامی است.');if($result==='conditional'&&$limitations===null)throw new TamiranApiException('محدودیت نتیجه مشروط الزامی است.');
        $rework=$pdo->prepare("SELECT COUNT(*) FROM repair_qc_runs WHERE case_id=:case AND result='failed'");$rework->execute(['case'=>$caseId]);$reworkNumber=(int)$rework->fetchColumn();$public=tamiran_id();$pdo->prepare('INSERT INTO repair_qc_runs(public_id,shop_id,case_id,template_id,performed_by_user_id,repaired_by_user_id,result,failure_reason,conditional_limitations,manager_override,override_reason,rework_number,idempotency_key) VALUES(:public,:shop,:case,:template,:actor,:repairer,:result,:failure,:limitations,:override,:override_reason,:rework,:idempotency)')->execute(['public'=>$public,'shop'=>$scope['shop_id'],'case'=>$caseId,'template'=>$templateId,'actor'=>$scope['actor']['id'],'repairer'=>$case['primary_technician_user_id'],'result'=>$result,'failure'=>$failure,'limitations'=>$limitations,'override'=>!empty($input['managerOverride'])&&$scope['role']==='repair_manager'?1:0,'override_reason'=>v2_text($input['overrideReason']??'','علت عبور اضطراری',1000,false),'rework'=>$reworkNumber,'idempotency'=>$idempotency]);$runId=(int)$pdo->lastInsertId();$insert=$pdo->prepare('INSERT INTO repair_qc_results(qc_run_id,template_item_id,custom_title,result,value_text,evidence_file_id,notes) VALUES(:run,:item,:custom,:result,:value,:evidence,:notes)');foreach($answers as$answer){$answerResult=(string)($answer['result']??'not_tested');if(!in_array($answerResult,['passed','failed','not_applicable','not_tested'],true))throw new TamiranApiException('نتیجه یکی از موارد چک‌لیست معتبر نیست.');$insert->execute(['run'=>$runId,'item'=>(int)$answer['templateItemId'],'custom'=>null,'result'=>$answerResult,'value'=>v2_text($answer['value']??'','مقدار',2000,false),'evidence'=>(int)($answer['evidenceFileId']??0)?:null,'notes'=>v2_text($answer['notes']??'','توضیحات',2000,false)]);}foreach($customAnswers as$answer){$customTitle=v2_text($answer['title']??'','عنوان تست سفارشی',240);$answerResult=(string)($answer['result']??'not_tested');if(!in_array($answerResult,['passed','failed','not_applicable','not_tested'],true))throw new TamiranApiException('نتیجه تست سفارشی معتبر نیست.');$notes=v2_text($answer['notes']??'','توضیحات تست سفارشی',2000,false);if($answerResult==='failed'&&$notes===null)throw new TamiranApiException('برای تست سفارشی مردود، توضیح الزامی است.');$insert->execute(['run'=>$runId,'item'=>null,'custom'=>$customTitle,'result'=>$answerResult,'value'=>null,'evidence'=>(int)($answer['evidenceFileId']??0)?:null,'notes'=>$notes]);}tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'qc.complete','repair_qc_run',$public,null,['result'=>$result,'reworkNumber'=>$reworkNumber,'customTests'=>count($customAnswers)]);if($result==='failed'&&(int)$case['primary_technician_user_id']>0)v2_notify($pdo,$scope,(int)$case['primary_technician_user_id'],'qc_failed','کنترل کیفیت پرونده مردود شد',$failure??'نیازمند بازکاری','repair_case',$case['case_public_id']);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}$transition=quality_route_after_run($pdo,$scope,$caseId,$result,$failure,$limitations,$idempotency);return['completed'=>true,'replayed'=>false,'publicId'=>$public,'case'=>$transition];
}

function quality_ack(PDO $pdo,array $scope,array $input):array
{
    $runPublic=v2_text($input['qcRunPublicId']??'','QC',80);$channel=(string)($input['channel']??'');if(!in_array($channel,['sms_otp','in_person_signature','secure_portal'],true))throw new TamiranApiException('روش تأیید محدودیت معتبر نیست.');$statement=$pdo->prepare("SELECT q.*,c.public_id AS case_public_id,cu.mobile FROM repair_qc_runs q INNER JOIN repair_cases c ON c.id=q.case_id INNER JOIN repair_customers cu ON cu.id=c.customer_id WHERE q.public_id=:public AND q.shop_id=:shop AND q.result='conditional' LIMIT 1");$statement->execute(['public'=>$runPublic,'shop'=>$scope['shop_id']]);$run=$statement->fetch();if(!is_array($run))throw new TamiranApiException('QC مشروط پیدا نشد.',404);if(in_array($channel,['sms_otp','secure_portal'],true)){if(!function_exists('tamiran_sms_verify_otp')||!tamiran_sms_verify_otp($pdo,$scope['shop_id'],'portal_action',$runPublic,tamiran_mobile($run['mobile']),(string)($input['otpRequestId']??''),(string)($input['otpCode']??'')))throw new TamiranApiException('کد یک‌بارمصرف معتبر نیست.',403);}elseif(!v2_has_permission($scope,'qc.record_customer_ack',['reception','quality_control']))throw new TamiranApiException('ثبت تأیید حضوری مجاز نیست.',403);$pdo->prepare('UPDATE repair_qc_runs SET customer_acknowledged_at=NOW(),customer_ack_channel=:channel WHERE id=:id AND customer_acknowledged_at IS NULL')->execute(['channel'=>$channel,'id'=>$run['id']]);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'qc.conditional_ack','repair_qc_run',$runPublic,null,['channel'=>$channel]);return['acknowledged'=>true];
}

tamiran_api(static function():array{$pdo=tamiran_db();$scope=v2_scope();v2_require_capability(v2_product_policy($pdo,$scope),'qcEnabled','کنترل کیفیت برای محصول یا تنظیمات این تعمیرگاه فعال نیست.');$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET')return quality_payload($pdo,$scope);if($method!=='POST')throw new TamiranApiException('روش درخواست مجاز نیست.',405);tamiran_require_csrf();$input=tamiran_json_body();return match((string)($input['action']??'')){'run'=>quality_run($pdo,$scope,$input),'ack_conditional'=>quality_ack($pdo,$scope,$input),default=>throw new TamiranApiException('عملیات QC معتبر نیست.'),};});
